m = json.load(open(R + 'seed/import/manifest.json')); have = {x['key'] for x in m}; n = 0
for f, i, t, y, pl, src, url, txt in D:
    if 'vph-' + i in have or not os.path.exists(V + f + '.jpg'): continue
    im = Image.open(V + f + '.jpg').convert('RGB')
    if max(im.size) > 2400: im.thumbnail((2400, 2400))
    fn = f'{i}.jpg'; tn = f'{i}-t.jpg'; im.save(R + 'seed/import/' + fn, quality=90); th = im.copy(); th.thumbnail((420, 420)); th.save(R + 'seed/import/' + tn, quality=80)
    m.append({'key': 'vph-' + i, 'kind': 'doc', 'id': i, 'files': [{'file': fn, 'thumb': tn}], 'data': {'title': t, 'date': y, 'place': pl, 'src': src, 'url': url, 'line': txt or '—', 'text': txt, 'people': []}})
    n += 1
json.dump(m, open(R + 'seed/import/manifest.json', 'w'), ensure_ascii=False, indent=1)
print('додано', n)
